import{_ as e,c as t,o,b0 as p}from"./chunks/framework.BWMBvyU7.js";const r="/programming-docs/assets/104612IS-0-1777980155662-13.BLS1KEn8.jpg",s="/programming-docs/assets/1046123342-1-1777980186499-15.hVVb9ULx.jpg",n="/programming-docs/assets/1046121126-2-1777980216662-17.uel1T7sW.jpg",l="/programming-docs/assets/1046122049-3-1777980257164-19.D7-98J8t.jpg",i="/programming-docs/assets/104612CJ-4-1777980295535-21.C5pqTAmQ.jpg",c="/programming-docs/assets/1046121323-5-1777981170475-23.59BIIBAI.jpg",X=JSON.parse('{"title":"LV540-内存分页机制实现简介","description":null,"frontmatter":{"title":"LV540-内存分页机制实现简介","date":"2026-05-05T19:22:11.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/memory/126d44370713093e9d1e5a19","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T19:22:11.147Z","fulluuid":"e9d1e5a192d7410d9885a211dee444eb","useduuid":"e9d1e5a19"}},"headers":[],"relativePath":"sdoc/Language/c/memory/126d44370713093e9d1e5a19.md","filePath":"sdoc/01-编程语言/01-C语言/30-内存管理/LV540-内存分页机制实现简介.md","lastUpdated":1777987950000}'),d={name:"sdoc/Language/c/memory/126d44370713093e9d1e5a19.md"};function m(g,a,_,u,h,A){return o(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="lv540-内存分页机制实现简介" tabindex="-1">LV540-内存分页机制实现简介 <a class="header-anchor" href="#lv540-内存分页机制实现简介" aria-label="Permalink to &quot;LV540-内存分页机制实现简介&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>现代操作系统都使用分页机制来管理内存，这使得每个程序都拥有自己的地址空间。每当程序使用虚拟地址进行读写时，都必须转换为实际的物理地址，才能真正在内存条上定位数据。如下图所示：</p><p><img src="'+r+'" alt="虚拟地址到物理地址的转换"></p><p>内存地址的转换是通过一种叫做**页表（Page Table）**的机制来完成的，这是本节要讲解的重点，即：</p><ul><li>页表是什么？为什么要采用页表机制，而不采用其他机制？</li><li>虚拟地址如何通过页表转换为物理地址？</li></ul><h2 id="二、-直接使用数组转换" tabindex="-1">二、 直接使用数组转换 <a class="header-anchor" href="#二、-直接使用数组转换" aria-label="Permalink to &quot;二、 直接使用数组转换&quot;">​</a></h2><p>最容易想到的映射方案是使用数组：每个数组元素保存一个物理地址，而把虚拟地址作为数组下标，这样就能够很容易地完成映射，并且效率不低。如下图所示：</p><p><img src="'+s+'" alt="使用数组进行地址映射"></p><p>但是这样的数组有 2^32 个元素，每个元素大小为 4 个字节，总共占用 16GB 的内存，显然是不现实的！</p><h2 id="三、-使用一级页表" tabindex="-1">三、 使用一级页表 <a class="header-anchor" href="#三、-使用一级页表" aria-label="Permalink to &quot;三、 使用一级页表&quot;">​</a></h2><p>既然内存是分页的，只要我们能够定位到数据所在的页，以及它在页内的偏移（也就是距离页开头的字节数），就能够转换为物理地址。例如，一个 int 类型的值保存在第 12 页，页内偏移为 240，那么对应的物理地址就是 2^12 * 12 + 240 = 49392。</p><blockquote><p>2^12 为一个页的大小，也就是 4K。</p></blockquote><p>虚拟地址空间大小为 4GB，总共包含 2^32 / 2^12 = 2^20 = 1K * 1K = 1M = 1048576 个页面，我们可以定义一个这样的数组：它包含 2^20 = 1M 个元素，每个元素的值为页面编号（也就是位于第几个页面），长度为 4 字节，整个数组共占用 4MB 的内存空间。这样的数组就称为<strong>页表（Page Table）</strong>，它记录了地址空间中所有页的编号。</p><p>虚拟地址长度为 32 位，我们不妨进行一下切割，将高 20 位作为页表数组的下标，低 12 位作为页内偏移。如下图所示：</p><p><img src="'+n+'" alt="虚拟地址切割方式"></p><p>为什么要这样切割呢？因为页表数组共有 2^20 = 1M 个元素，使用虚拟地址的高 20 位作为下标，正好能够访问数组中的所有元素；并且，一个页面的大小为 2^12 = 4KB，使用虚拟地址的低 12 位恰好能够表示所有偏移。</p><p>注意，表示页面编号只需要 20 位，而页表数组的每个元素的长度却为 4 字节，即 32 位，多出 32 - 20 = 12 位。这 12 位也有很大的用处，可以用来表示当前页的相关属性，例如是否有读写权限、是否已经分配物理内存、是否被换出到硬盘等。</p><p>例如一个虚拟地址 0XA010BA01，它的高 20 位是 0XA010B，所以需要访问页表数组的第 0XA010B 个元素，才能找到数据所在的物理页面。假设页表数组第 0XA010B 个元素的值为 0X0F70AAA0，它的高 20 位为 0X0F70A，那么就可以确定<strong>数据位于第 0X0F70A 个物理页面</strong>。再来看虚拟地址，它的低 12 位是 0XA01，所以<strong>页内偏移也是 0XA01</strong>。有了页面索引和页内偏移，就可以算出物理地址了。经过计算，最终的物理地址为 0X0F70A * 2^12 + 0XA01 = 0X0F70A000 + 0XA01 = 0X0F70AA01。</p><p>这种思路所形成的映射关系如下图所示：</p><p><img src="'+l+'" alt="一级页表映射关系"></p><p>可以发现，有的页被映射到物理内存，有的被映射到硬盘，不同的映射方式可以由页表数组元素的低 12 位来控制。</p><p>使用这种方案，不管程序占用多大的内存，都要为页表数组分配 4M 的内存空间（页表数组也必须放在物理内存中），因为虚拟地址空间中的高 1G 或 2G 是被系统占用的，必须保证较大的数组下标有效。</p><p>现在硬件很便宜了，内存容量大了，很多电脑都配备 4G 或 8G 的内存，页表数组占用 4M 内存或许不觉得多，但在 32 位系统刚刚发布的时候，内存还是很紧缺的资源，很多电脑才配备 100M 甚至几十兆的内存，4M 内存就显得有点大了，所以还得对上面的方案进行改进，压缩页表数组所占用的内存。</p><h2 id="四、-使用两级页表" tabindex="-1">四、 使用两级页表 <a class="header-anchor" href="#四、-使用两级页表" aria-label="Permalink to &quot;四、 使用两级页表&quot;">​</a></h2><p>上面的页表共有 2^20 = 2^10 * 2^10 个元素，为了压缩页表的存储空间，可以将上面的页表分拆成 2^10 = 1K = 1024 个小的页表，这样每个页表只包含 2^10 = 1K = 1024 个元素，占用 2^10 * 4 = 4KB 的内存，也即一个页面的大小。这 1024 个小的页表，可以存储在不同的物理页，它们之间可以是不连续的。</p><p>那么问题来了，既然这些小的页表分散存储，位于不同的物理页，该如何定位它们呢？也就是如何记录它们的编号（也即在物理内存中位于第几个页面）。</p><p>1024 个页表有 1024 个索引，所以不能用一个指针指向它们，必须将这些索引再保存到一个额外的数组中。这个额外的数组有 1024 个元素，每个元素记录一个页表所在物理页的编号，长度为 4 个字节，总共占用 4KB 的内存。我们将这个额外的数组称为<strong>页目录（Page Directory）</strong>，因为它的每一个元素对应一个页表。</p><p>如此，只要使用一个指针来记住页目录的地址即可，等到进行地址转换时，可以根据这个指针找到页目录，再根据页目录找到页表，最后找到物理地址，前后共经过 3 次间接转换。</p><p>那么，如何根据虚拟地址找到页目录和页表中相应的元素呢？我们不妨将虚拟地址分割为三分部，高 10 位作为页目录中元素的下标，中间 10 位作为页表中元素的下标，最后 12 位作为页内偏移，如下图所示：</p><p><img src="'+i+'" alt="两级页表虚拟地址切割"></p><p>前面我们说过，知道了物理页的索引和页内偏移就可以转换为物理地址了，在这种方案中，页内偏移可以从虚拟地址的低 12 位得到，但是物理页索引却保存在 1024 个分散的小页表中，所以就必须先根据页目录找到对应的页表，再根据页表找到物理页索引。</p><p>例如一个虚拟地址 0011000101 1010001100 111100001010，它的高 10 位为 0011000101，对应页目录中的第 0011000101 个元素，假设该元素的高 20 位为 0XF012A，也即对应的页表在物理内存中的编号为 0XF012A，这样就找到了页表。虚拟地址中间 10 位为 1010001100，它对应页表中的第 1010001100 个元素，假设该元素的高 20 位为 0X00D20，也即物理页的索引为 <strong>0X00D20</strong>。通过计算，最终的物理地址为 <strong>0X00D20</strong> * 2^12 + <strong>111100001010</strong> = 0X00D20F0A。</p><p>这种思路所形成的映射关系如下图所示：</p><p><img src="'+c+'" alt="两级页表映射关系"></p><blockquote><p>图中的点状虚线说明了最终的映射关系。图中没有考虑映射到硬盘的情况。</p></blockquote><p>采用这样的两级页表的一个明显优点是，如果程序占用的内存较少，分散的小页表的个数就会远远少于 1024 个，只会占用很少的一部分存储空间（远远小于 4M）。</p><p>在极少数的情况下，程序占用的内存非常大，布满了 4G 的虚拟地址空间，这样小页表的数量可能接近甚至等于 1024，再加上页目录占用的存储空间，总共是 4MB+4KB，比上面使用一级页表的方案仅仅多出 4KB 的内存。这是可以容忍的，因为很少出现如此极端的情况。</p><p>也就是说，使用两级页表后，页表占用的内存空间不固定，它和程序本身占用的内存空间成正比，从整体上来看，会比使用一级页表占用的内存少得多。</p><h2 id="五、-使用多级页表" tabindex="-1">五、 使用多级页表 <a class="header-anchor" href="#五、-使用多级页表" aria-label="Permalink to &quot;五、 使用多级页表&quot;">​</a></h2><p>对于 64 位环境，虚拟地址空间达到 256TB，使用二级页表占用的存储空间依然不小，所以会更加细化，从而使用三级页表甚至多级页表，这样就会有多个页目录，虚拟地址也会被分割成多个部分，思路和上面是一样的，不再赘述。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',43)])])}const B=e(d,[["render",m]]);export{X as __pageData,B as default};
